:root {
    --black: #000000;
    --white: #FFFFFF;
    --accent: #CAFF00;
    --font-serif: 'Bebas Neue', sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
    --noise-opacity: 0.08;
    --transition-fast: 0.2s;
    --transition-normal: 0.4s;
    --transition-slow: 0.8s;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
    height: 100%;
}

body {
    background-color: var(--black);
    color: var(--white);
    font-family: var(--font-mono);
    overflow-x: hidden;
    min-height: 100%;
    position: relative;
}

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--black);
    color: var(--white);
    padding: 10px;
    z-index: 100;
    transition: top 0.3s;
}

.skip-link:focus {
    top: 0;
}

::selection {
    background: var(--accent);
    color: var(--black);
}

/* Noise texture */
.hero-noise {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background-image: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><filter id="noise"><feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves="4" stitchTiles="stitch"/></filter><rect width="100%" height="100%" filter="url(%23noise)" opacity="0.05"/></svg>');
    pointer-events: none;
    z-index: 10;
}

/* Header & Navigation */
.header {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    padding: 2rem;
    z-index: 1000;
    display: flex;
    justify-content: flex-end;
}

.nav-list {
    display: flex;
    gap: 2rem;
    list-style: none;
}

.nav-link {
    font-family: var(--font-mono);
    font-size: 0.8rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--white);
    text-decoration: none;
    transition: color var(--transition-normal);
    position: relative;
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 100%;
    height: 1px;
    background: var(--accent);
    transform: scaleX(0);
    transform-origin: right;
    transition: transform var(--transition-normal);
}

.nav-link:hover::after {
    transform: scaleX(1);
    transform-origin: left;
}

.nav-link:hover {
    color: var(--accent);
}

/* Hero Section */
.hero {
    position: relative;
    height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.hero-content {
    z-index: 20;
    position: relative;
}

.hero-text {
    font-family: var(--font-serif);
    font-size: clamp(80px, 20vw, 250px);
    font-weight: 400;
    letter-spacing: -0.02em;
    text-transform: uppercase;
}

/* Marquee Sections */
.marquee-section {
    width: 100%;
    overflow: hidden;
    padding: 2rem 0;
    position: relative;
}

.marquee {
    display: flex;
    white-space: nowrap;
    will-change: transform;
}

.marquee-content {
    flex-shrink: 0;
    display: flex;
    align-items: center;
}

.marquee-text {
    font-family: var(--font-mono);
    font-size: clamp(1rem, 4vw, 2.5rem);
    font-weight: 500;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    padding: 0 2rem;
}

.marquee-outline {
    -webkit-text-stroke: 1px var(--accent);
    -webkit-text-fill-color: transparent;
    color: transparent;
}

/* Work Section */
.work-section {
    padding: 4rem 2rem;
    position: relative;
}

.work-container {
    max-width: 1600px;
    margin: 0 auto;
}

.work-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 4rem;
    padding-bottom: 2rem;
    border-bottom: 1px solid var(--white);
}

.work-title {
    font-family: var(--font-serif);
    font-size: clamp(3rem, 8vw, 8rem);
    font-weight: 400;
    letter-spacing: -0.02em;
    text-transform: uppercase;
}

.work-number {
    font-family: var(--font-mono);
    font-size: 2rem;
    font-weight: 500;
}

.work-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 2rem;
    perspective: 1000px;
}

@media (min-width: 768px) {
    .work-grid {
        grid-template-columns: 1fr 1fr;
    }
}

@media (min-width: 1024px) {
    .work-grid {
        grid-template-columns: 1fr 1fr 1fr;
    }
}

.project-card {
    position: relative;
    background: var(--black);
    border: 1px solid var(--white);
    overflow: hidden;
    transition: transform var(--transition-normal), box-shadow var(--transition-normal);
    cursor: pointer;
}

.project-card:hover {
    transform: translateY(-10px) rotateX(15deg);
    box-shadow: 0 20px 40px rgba(202, 255, 0, 0.2);
}

.project-number {
    position: absolute;
    top: 1rem;
    left: 1rem;
    font-family: var(--font-mono);
    font-size: 0.8rem;
    z-index: 2;
}

.project-image {
    width: 100%;
    height: 300px;
    background-size: cover;
    background-position: center;
    transition: transform 0.6s ease;
}

.project-card:hover .project-image {
    transform: scale(1.05);
}

.project-content {
    padding: 2rem;
}

.project-title {
    font-family: var(--font-serif);
    font-size: 1.8rem;
    margin-bottom: 1rem;
    letter-spacing: -0.01em;
}

.project-meta {
    display: flex;
    gap: 1rem;
    font-size: 0.8rem;
    letter-spacing: 0.05em;
    text-transform: uppercase;
}

/* Footer */
.footer {
    background: var(--black);
    padding: 4rem 2rem;
    border-top: 1px solid var(--white);
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
}

.footer-content {
    text-align: center;
    width: 100%;
}

.footer-title {
    font-family: var(--font-serif);
    font-size: clamp(4rem, 15vw, 12rem);
    font-weight: 400;
    letter-spacing: -0.02em;
    margin-bottom: 2rem;
    line-height: 0.9;
}

.footer-email {
    font-family: var(--font-mono);
    font-size: 1.2rem;
    color: var(--white);
    text-decoration: none;
    transition: color var(--transition-normal);
}

.footer-email:hover {
    color: var(--accent);
}

/* Magnetic cursor */
.cursor-magnetic {
    transition: transform 0.2s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

/* Responsive adjustments */
@media (max-width: 767px) {
    .header {
        padding: 1rem;
    }

    .nav-list {
        gap: 1rem;
    }

    .nav-link {
        font-size: 0.7rem;
    }

    .hero-text {
        font-size: clamp(60px, 25vw, 150px);
    }

    .marquee-text {
        font-size: 1rem;
        padding: 0 1rem;
    }

    .work-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 1rem;
    }

    .work-number {
        font-size: 1.5rem;
    }

    .project-image {
        height: 200px;
    }

    .project-content {
        padding: 1.5rem;
    }
}

// Magnetic Cursor
const cursor = document.createElement('div');
cursor.classList.add('cursor-magnetic');
cursor.style.position = 'fixed';
cursor.style.width = '24px';
cursor.style.height = '24px';
cursor.style.borderRadius = '50%';
cursor.style.backgroundColor = 'transparent';
cursor.style.border = '1px solid var(--accent)';
cursor.style.zIndex = '9999';
cursor.style.pointerEvents = 'none';
cursor.style.transition = 'transform 0.2s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
document.body.appendChild(cursor);

let mouseX = 0;
let mouseY = 0;
let cursorX = 0;
let cursorY = 0;

window.addEventListener('mousemove', (e) => {
    mouseX = e.clientX;
    mouseY = e.clientY;
});

const animateCursor = () => {
    cursorX += (mouseX - cursorX) * 0.1;
    cursorY += (mouseY - cursorY) * 0.1;
    cursor.style.transform = `translate(${cursorX - 12}px, ${cursorY - 12}px)`;
    requestAnimationFrame(animateCursor);
};

animateCursor();

// Project Card Tilt Effect
document.querySelectorAll('.project-card').forEach(card => {
    card.addEventListener('mousemove', (e) => {
        const rect = card.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        const centerX = rect.width / 2;
        const centerY = rect.height / 2;
        const dX = (x - centerX) / centerX;
        const dY = (y - centerY) / centerY;

        card.style.transform = `translateY(-10px) rotateX(${dY * 10}deg) rotateY(${dX * -10}deg)`;
    });

    card.addEventListener('mouseleave', () => {
        card.style.transform = 'translateY(0) rotateX(0) rotateY(0)';
    });
});

// Smooth scroll and parallax effects
window.addEventListener('scroll', () => {
    const scrolled = window.pageYOffset;
    const parallax = document.querySelector('.hero');
    if (parallax) {
        const speed = scrolled * 0.5;
        parallax.style.transform = `translateY(${speed}px)`;
    }
});

// Marquee Animation
const marquees = document.querySelectorAll('.marquee');

marquees.forEach(marquee => {
    const content = marquee.querySelector('.marquee-content');
    const clone = content.cloneNode(true);
    marquee.appendChild(clone);

    const marqueeWidth = marquee.offsetWidth;
    const contentWidth = content.offsetWidth;

    let scrollAmount = 0;
    const animationSpeed = 0.1;

    const animateMarquee = () => {
        scrollAmount -= animationSpeed;
        if (scrollAmount <= -contentWidth) {
            scrollAmount = 0;
        }
        content.style.transform = `translateX(${scrollAmount}px)`;
        requestAnimationFrame(animateMarquee);
    };

    animateMarquee();
});
